previewCss:
.darma-loader-darma-b17-cement-mixer { --accent: var(--loader-color, #ca8a04); --accent-2: var(--loader-secondary-color, #94a3b8); width: var(--loader-size, 124px); height: calc(var(--loader-size, 124px) * .74); position: relative; }
.darma-loader-darma-b17-cement-mixer .darma-loader-darma-b17-cement-mixer__drum { position: absolute; left: 12%; top: 6%; width: 50%; height: 68%; border-radius: 50%; background: repeating-conic-gradient(from 0deg at 50% 50%, var(--accent) 0 12%, color-mix(in srgb, #fff 26%, var(--accent)) 0 24%); transform: rotate(-16deg); animation: darma-loader-darma-b17-cement-mixer-mixer-turn calc(var(--loader-speed, 1s) * 2.2) linear infinite; }
.darma-loader-darma-b17-cement-mixer .darma-loader-darma-b17-cement-mixer__chute { position: absolute; left: 62%; top: 34%; width: 30%; height: 16%; border-radius: 4px 8px 8px 4px; background: linear-gradient(var(--accent-2), color-mix(in srgb, #000 25%, var(--accent-2))); transform: rotate(16deg); }
.darma-loader-darma-b17-cement-mixer .darma-loader-darma-b17-cement-mixer__frame { position: absolute; left: 6%; right: 6%; bottom: 20%; height: 14%; border-radius: 4px; background: linear-gradient(var(--accent-2), color-mix(in srgb, #000 30%, var(--accent-2))); }
.darma-loader-darma-b17-cement-mixer .darma-loader-darma-b17-cement-mixer__wheel { position: absolute; bottom: 2%; width: 20%; height: 26%; border-radius: 50%; background: radial-gradient(circle, #64748b 0 30%, #1e293b 32%); animation: darma-loader-darma-b17-cement-mixer-mixer-roll calc(var(--loader-speed, 1s) * 2.2) linear infinite; }
.darma-loader-darma-b17-cement-mixer .darma-loader-darma-b17-cement-mixer__wheel:nth-of-type(4) { left: 12%; }
.darma-loader-darma-b17-cement-mixer .darma-loader-darma-b17-cement-mixer__wheel:nth-of-type(5) { right: 12%; }
@keyframes darma-loader-darma-b17-cement-mixer-mixer-turn { from { transform: rotate(-16deg); } to { transform: rotate(344deg); } }
@keyframes darma-loader-darma-b17-cement-mixer-mixer-roll { to { transform: rotate(1turn); } }

